create table public.user_roles (user_id uuid primary key references auth.users(id) on delete cascade, role text not null check(role in ('admin','user')) default 'user');
create table public.template_status (template_id text primary key, status text not null default 'published' check(status in ('published','hidden','archived')));
create table public.projects (id uuid primary key, user_id uuid not null references auth.users(id) on delete cascade, document jsonb not null check (pg_column_size(document)< 12000000), updated_at timestamptz not null default now());
create table public.downloads (id bigint generated always as identity primary key, user_id uuid not null references auth.users(id) on delete cascade, template_id text not null, downloaded_at timestamptz not null default now());
create table public.admin_audit (id bigint generated always as identity primary key, user_id uuid references auth.users(id), template_id text not null, old_status text, new_status text, created_at timestamptz not null default now());
alter table public.user_roles enable row level security;
alter table public.template_status enable row level security;
alter table public.projects enable row level security;
alter table public.downloads enable row level security;
alter table public.admin_audit enable row level security;
create function public.is_forma_admin() returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.user_roles where user_id=auth.uid() and role='admin') $$;
revoke all on function public.is_forma_admin() from public;
grant execute on function public.is_forma_admin() to authenticated;
create policy own_role on public.user_roles for select to authenticated using (user_id=auth.uid());
create policy public_status on public.template_status for select to anon, authenticated using(true);
create policy admin_status_insert on public.template_status for insert to authenticated with check((select public.is_forma_admin()));
create policy admin_status_update on public.template_status for update to authenticated using((select public.is_forma_admin())) with check((select public.is_forma_admin()));
create policy own_projects on public.projects for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy own_downloads on public.downloads for select to authenticated using(user_id=auth.uid() or (select public.is_forma_admin()));
create policy audit_admin on public.admin_audit for select to authenticated using((select public.is_forma_admin()));
create function public.log_forma_status() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.admin_audit(user_id,template_id,old_status,new_status) values(auth.uid(),new.template_id,case when TG_OP='UPDATE' then old.status else null end,new.status); return new; end $$;
create trigger forma_status_audit after insert or update on public.template_status for each row execute function public.log_forma_status();
revoke insert,update,delete on public.user_roles from anon,authenticated;
revoke insert,update,delete on public.downloads from anon,authenticated;
revoke insert,update,delete on public.admin_audit from anon,authenticated;
